""" convert CIE1976 'v' to CIE1960 uv coordinates
    :param u76: ' value (CIE1976)
    :param v76: v' value (CIE1976)
    :return: CIE1960 u, v """
def uv76_to_uv60(u76: Any, v76: Any) -> object {
    v60 = (2 * v76) / 3;
    return (u76, v60);
}

""" returns the factorial of n """
def factorial(n: Any) -> object {
    if (n < 0) {
        return None;
    }
    if (n == 0) {
        return 1;
    }
    if (n < 2) {
        return 1;
    }
    return (n * factorial((n - 1)));
}

