"""
    Find the index of a letter in a word starting the search at specific index
    """
def find(word: Any, letter: Any, start_index: Any) -> object {
    index = start_index;
    while (index < len(word)) {
        if (word[index] == letter) {
            return index;
        }
        index += 1;
    }
    return -1;
}

